#include "dispatch.h"
#include "oracle.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static unsigned checks;
#define CHECK(x) do{assert(x);checks++;}while(0)
static void put(uint8_t*p,uint32_t n){for(unsigned j=0;j<4;j++)p[j]=(uint8_t)(n>>(8*j));}
static QcaRxEvent event(uint32_t id,unsigned type,unsigned reason,unsigned frequency){QcaRxEvent e={.completion=id,.event=WMI_TLV_SCAN_EVENTID,.bytes=32,.endpoint=1,.pipe=2};put(e.payload,WMI_TLV_SCAN_EVENTID);put(e.payload+4,24|(WMI_TLV_TAG_STRUCT_SCAN_EVENT<<16));struct wmi_scan_event value={.event_type=type,.reason=reason,.channel_freq=frequency,.scan_req_id=0xa008,.scan_id=0xa007,.vdev_id=0};memcpy(e.payload+8,&value,sizeof(value));return e;}
static void setup(QcaStationDispatch*d,QcaStationScan*s,QcaHtcCredit*c){memset(d,0,sizeof(*d));memset(s,0,sizeof(*s));memset(c,0,sizeof(*c));QcaHtcReady r={.credits=2,.credit_size=1792,.endpoints=4};QcaHtcConnection w={.service=256,.max_bytes=1784,.endpoint=1};CHECK(qca_htc_credit_begin(c,&r,&w));uint32_t ticket;CHECK(qca_htc_credit_reserve(c,144,&ticket));CHECK(qca_htc_credit_commit(c,ticket));s->credit=c;s->phase=QCA_STA_SCAN_POSTED;s->frame_bytes=144;s->scan=7;s->request=8;s->count=2;s->frequencies[0]=2412;s->frequencies[1]=2437;CHECK(qca_station_dispatch_begin(d,s,0));}
static void unchanged(QcaHtcCredit*c,QcaHtcCredit old){CHECK(!memcmp(c,&old,sizeof(old)));}
int main(void){QcaStationDispatch d;QcaStationScan s;QcaHtcCredit c;QcaRxEvent e,out;setup(&d,&s,&c);
 /* Real RX-pump credit semantics: consume incremental report once, before event
  * offering. Payload event has no trailer representation to apply again. */
 QcaHtcFrame credit={.endpoint=1};credit.credits[1]=1;CHECK(qca_htc_credit_receive(&c,&credit));QcaHtcCredit old=c;
 e=event(3,WMI_SCAN_EVENT_STARTED,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);CHECK(s.started&&s.phase==QCA_STA_SCAN_POSTED&&s.last_rx==3);unchanged(&c,old);
 e=event(10,WMI_SCAN_EVENT_COMPLETED,WMI_SCAN_REASON_COMPLETED,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);CHECK(s.result==QCA_SCAN_DONE&&s.phase==QCA_STA_SCAN_POSTED);CHECK(qca_station_scan_complete(&s,144));CHECK(s.phase==QCA_STA_SCAN_TERMINAL);unchanged(&c,old);CHECK(qca_station_dispatch_offer(&d,&e)==-1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_EMPTY);unchanged(&c,old);
 setup(&d,&s,&c);s.phase=QCA_STA_CREATE_POSTED;s.frame_bytes=36;e=event(2,1,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SEQUENCE&&d.count==1&&!s.started);CHECK(qca_station_scan_complete(&s,36));CHECK(s.phase==QCA_STA_CREATE_ORDERED&&!s.started&&s.result==QCA_SCAN_NONE);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SEQUENCE);CHECK(qca_station_dispatch_take(&d,2,&out,sizeof(out))&&out.completion==2);
 setup(&d,&s,&c);e=(QcaRxEvent){.completion=1,.pipe=1,.endpoint=0,.event=0,.bytes=2,.payload={9,0}};CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_UNMATCHED);QcaRxEvent unknown={.completion=4,.event=0x123456,.bytes=8,.pipe=2,.endpoint=1};put(unknown.payload,unknown.event);CHECK(qca_station_dispatch_offer(&d,&unknown)==1);e=event(5,1,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==0&&d.last_completion==4);CHECK(!qca_station_dispatch_take(&d,4,&out,sizeof(out)));CHECK(qca_station_dispatch_take(&d,1,&out,sizeof(out))&&!memcmp(&out.payload,&d.owned[0].payload,sizeof(out.payload)));CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_UNMATCHED);CHECK(qca_station_dispatch_take(&d,4,&out,sizeof(out)));CHECK(out.event==unknown.event);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);
 for(unsigned which=0;which<3;which++){setup(&d,&s,&c);e=event(1,1,0,0);put(e.payload+(which==0?20:which==1?24:28),which==2?1:0xa009);old=c;CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_UNMATCHED&&d.count==1&&!s.started);unchanged(&c,old);CHECK(qca_station_dispatch_take(&d,1,&out,sizeof(out)));}
 setup(&d,&s,&c);e=event(7,1,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);e=event(8,1,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SEQUENCE&&d.count==1);CHECK(qca_station_dispatch_take(&d,8,&out,sizeof(out)));e=event(20,8,0,5180);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SEQUENCE);CHECK(qca_station_dispatch_take(&d,20,&out,sizeof(out)));e=event(22,8,0,2437);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);
 for(unsigned at=4;at<32;at++)for(unsigned value=0;value<256;value++){
  setup(&d,&s,&c);old=c;e=event(9,1,0,0);e.payload[at]=value;CHECK(qca_station_dispatch_offer(&d,&e)==1);QcaStationScan prior=s;int rc=qca_station_dispatch_head(&d);if(rc!=QCA_DISPATCH_SCAN)CHECK(d.count==1&&!memcmp(&s,&prior,sizeof(s)));else checks++;unchanged(&c,old);
 }
 for(unsigned n=4;n<32;n++){setup(&d,&s,&c);e=event(1,1,0,0);e.bytes=n;CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_MALFORMED&&d.count==1);}
 setup(&d,&s,&c);e=event(1,1,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);s.scan=9;CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_MALFORMED&&d.count==1);s.scan=7;CHECK(!qca_station_dispatch_take(&d,1,&d.owned[0],sizeof(out)));CHECK(!qca_station_dispatch_take(&d,1,&out,sizeof(out)-1));CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);CHECK(!qca_station_dispatch_take(&d,1,&out,sizeof(out)));
 setup(&d,&s,&c);e=event(1,1,0,0);e.bytes=36;put(e.payload+32,0|(99u<<16));CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_UNMATCHED&&d.count==1);
 for(unsigned kind=0;kind<6;kind++){setup(&d,&s,&c);e=event(1,1,0,0);if(kind==0)e.completion=0;if(kind==1)e.bytes=2041;if(kind==2)e.endpoint=2;if(kind==3)e.pipe=3;if(kind==4)e.event++;if(kind==5)e.bytes=3;CHECK(qca_station_dispatch_offer(&d,&e)==-1&&!d.count&&!d.last_completion);}
 setup(&d,&s,&c);e=event(UINT32_MAX,1,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==1);CHECK(qca_station_dispatch_head(&d)==QCA_DISPATCH_SCAN);e=event(1,2,0,0);CHECK(qca_station_dispatch_offer(&d,&e)==-1);
 printf("checks=%u owned-dispatch/gaps/once-only-credit/ordering PASS\n",checks);return 0;}
